use super::{Generator, RustcDatatype};
use charon_lib::ast::*;
use charon_lib::ids::IndexVec;
use itertools::Itertools;
use std::fmt;

impl Generator<'_> {
    pub(super) fn ast_defs(&self) -> impl fmt::Display + '_ {
        fmt::from_fn(move |f| self.fmt_ast_defs(f))
    }

    fn fmt_ast_defs(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(
            f,
            "// This file is automatically generated by `cargo run --bin generate-asts`."
        )?;
        writeln!(f, "// Do not edit it by hand.")?;
        writeln!(f)?;
        writeln!(
            f,
            "#![allow(clippy::doc_lazy_continuation, clippy::enum_variant_names, clippy::large_enum_variant)]"
        )?;
        writeln!(f)?;
        writeln!(f, "use crate::ast::meta::Span;")?;
        writeln!(
            f,
            "use derive_generic_visitor::{{Drive, DriveMut, DriveTwo}};"
        )?;
        writeln!(f, "use serde::{{Deserialize, Serialize}};")?;
        writeln!(f, "use ustr::Ustr;")?;
        writeln!(f)?;
        writeln!(f, "#[derive(Debug, Clone, Copy, PartialEq, Eq)]")?;
        writeln!(f, "pub struct FromRustcError;")?;
        writeln!(f)?;

        while let Some(decl) = self.next_decl() {
            self.fmt_decl(f, decl)?;
            writeln!(f)?;
        }
        Ok(())
    }

    fn fmt_decl(&self, f: &mut fmt::Formatter<'_>, decl: &TypeDecl) -> fmt::Result {
        match &decl.kind {
            TypeDeclKind::Struct(fields) | TypeDeclKind::Union(fields) => {
                self.fmt_struct(f, decl.def_id, fields)
            }
            TypeDeclKind::Enum(_) => self.fmt_enum(f, decl),
            TypeDeclKind::Alias(ty) => {
                self.fmt_doc_attrs(f, &decl.item_meta.attr_info)?;
                writeln!(
                    f,
                    "pub type {} = {};",
                    self.type_name(decl.def_id),
                    self.generated_type(ty),
                )
            }
            TypeDeclKind::Opaque | TypeDeclKind::Error(_) => unreachable!(),
        }
    }

    fn fmt_struct(
        &self,
        f: &mut fmt::Formatter<'_>,
        id: TypeDeclId,
        fields: &IndexVec<FieldId, Field>,
    ) -> fmt::Result {
        let name = self.type_name(id);
        self.fmt_type_attrs(f, &self.crate_data[id], false)?;
        if fields.is_empty() {
            writeln!(f, "pub struct {name};")
        } else if fields.iter().all(|field| !field.is_positional) {
            writeln!(f, "pub struct {name} {{")?;
            for field in fields {
                self.fmt_named_field(f, field, "pub ")?;
            }
            writeln!(f, "}}")
        } else {
            writeln!(f, "pub struct {name}(")?;
            for field in fields {
                self.fmt_tuple_field(f, field, "pub ")?;
            }
            writeln!(f, ");")
        }
    }

    fn fmt_enum(&self, f: &mut fmt::Formatter<'_>, decl: &TypeDecl) -> fmt::Result {
        self.fmt_type_attrs(f, decl, true)?;
        writeln!(f, "pub enum {} {{", self.type_name(decl.def_id))?;
        for variant in self.variants(decl) {
            self.fmt_variant(f, variant)?;
        }
        writeln!(f, "}}")
    }

    fn fmt_variant(&self, f: &mut fmt::Formatter<'_>, variant: &Variant) -> fmt::Result {
        self.fmt_doc_attrs(f, &variant.attr_info)?;
        let name = &variant.name;
        let fields = &variant.fields;
        if fields.is_empty() {
            writeln!(f, "{name},")
        } else if fields.iter().all(|field| !field.is_positional) {
            writeln!(f, "{name} {{")?;
            for field in fields {
                self.fmt_named_field(f, field, "")?;
            }
            writeln!(f, "}},")
        } else {
            writeln!(f, "{name}(")?;
            for field in fields {
                self.fmt_tuple_field(f, field, "")?;
            }
            writeln!(f, "),")
        }
    }

    fn fmt_named_field(
        &self,
        f: &mut fmt::Formatter<'_>,
        field: &Field,
        visibility: &str,
    ) -> fmt::Result {
        self.fmt_doc_attrs(f, &field.attr_info)?;
        writeln!(
            f,
            "{visibility}{}: {},",
            field.name,
            self.generated_type(&field.ty),
        )
    }

    fn fmt_tuple_field(
        &self,
        f: &mut fmt::Formatter<'_>,
        field: &Field,
        visibility: &str,
    ) -> fmt::Result {
        self.fmt_doc_attrs(f, &field.attr_info)?;
        writeln!(f, "{visibility}{},", self.generated_type(&field.ty))
    }

    pub(super) fn generated_type<'a>(&'a self, ty: &'a Ty) -> impl fmt::Display + 'a {
        fmt::from_fn(move |f| self.fmt_generated_type(f, ty))
    }

    pub(super) fn fmt_generated_type(&self, f: &mut fmt::Formatter<'_>, ty: &Ty) -> fmt::Result {
        match ty.kind() {
            TyKind::Literal(lit) => write!(f, "{lit}"),
            TyKind::Adt(tref) => self.fmt_generated_adt_type(f, tref),
            TyKind::Array(ty, ..) | TyKind::Slice(ty, _) => {
                write!(f, "Vec<{}>", self.generated_type(ty))
            }
            TyKind::Ref(_, ty, _) => self.fmt_generated_type(f, ty),
            TyKind::Never => write!(f, "()"),
            unsupported => self.unsupported_type(format!("{unsupported:?}")),
        }
    }

    fn fmt_generated_adt_type(
        &self,
        f: &mut fmt::Formatter<'_>,
        tref: &TypeDeclRef,
    ) -> fmt::Result {
        match tref.as_builtin() {
            None => match self.datatype_for(tref.id) {
                Some(RustcDatatype::Special {
                    fmt_type: generated_type,
                    ..
                }) => generated_type(self, f, &tref.generics),
                _ if self.enqueue(tref.id) => write!(f, "{}", self.type_name(tref.id)),
                _ => self.unsupported_type(self.debug_type_name(tref.id)),
            },
            Some(BuiltinTy::Tuple) => self.fmt_tuple_type(f, &tref.generics.types),
            Some(BuiltinTy::Box) => {
                let ty = tref.generics.types.iter().next().unwrap();
                write!(f, "Box<{}>", self.generated_type(ty))
            }
            Some(BuiltinTy::Str) => write!(f, "Ustr"),
        }
    }

    fn fmt_tuple_type(
        &self,
        f: &mut fmt::Formatter<'_>,
        fields: &IndexVec<TypeVarId, Ty>,
    ) -> fmt::Result {
        match fields.len() {
            0 => write!(f, "()"),
            1 => write!(f, "({},)", self.generated_type(&fields[TypeVarId::ZERO])),
            _ => write!(
                f,
                "({})",
                fields
                    .iter()
                    .format_with(", ", |field, f| f(&self.generated_type(field)))
            ),
        }
    }

    fn fmt_doc_attrs(&self, f: &mut fmt::Formatter<'_>, attr_info: &AttrInfo) -> fmt::Result {
        for doc in attr_info
            .attributes
            .iter()
            .filter_map(|attr| attr.as_doc_comment())
        {
            if doc.is_empty() {
                writeln!(f, "///")?;
            } else {
                for line in doc.lines() {
                    writeln!(f, "///{line}")?;
                }
            }
        }
        Ok(())
    }

    fn fmt_type_attrs(
        &self,
        f: &mut fmt::Formatter<'_>,
        decl: &TypeDecl,
        is_enum: bool,
    ) -> fmt::Result {
        let rename = format!("Rustc{}", self.type_name(decl.def_id));
        self.fmt_doc_attrs(f, &decl.item_meta.attr_info)?;
        writeln!(
            f,
            "#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Drive, DriveMut, DriveTwo)]"
        )?;
        writeln!(
            f,
            "#[cfg_attr(feature = \"charon_on_charon\", charon::rename(\"{rename}\"))]"
        )?;
        if is_enum {
            writeln!(
                f,
                "#[cfg_attr(feature = \"charon_on_charon\", charon::variants_prefix(\"{rename}\"))]"
            )?;
        }
        Ok(())
    }
}
